/// Returns production-qualified profiles for the exact build target.
pub fn built_in_local_profiles() -> Result<Vec<RegisteredLocalProfile>, LocalAgentFailure> {
    built_in_local_profiles_for(LaunchFlavor::Production)
}

#[cfg(feature = "qualification-failpoints")]
/// Returns the exact immutable profile roster exercised by live qualification.
pub fn built_in_qualification_local_profiles()
-> Result<Vec<RegisteredLocalProfile>, LocalAgentFailure> {
    built_in_local_profiles_for(LaunchFlavor::Qualification)
}

#[cfg(any(test, feature = "testkit-agent"))]
/// Returns only the explicitly testkit-available profile set.
pub fn built_in_testkit_local_profiles() -> Result<Vec<RegisteredLocalProfile>, LocalAgentFailure> {
    built_in_local_profiles_for(LaunchFlavor::Testkit)
}

fn built_in_local_profiles_for(
    flavor: LaunchFlavor,
) -> Result<Vec<RegisteredLocalProfile>, LocalAgentFailure> {
    validate_launch_projection()?;
    let mut values = Vec::with_capacity(5);
    if RegisteredProfile::OpentofuPlansCreate.is_available_for(flavor) {
        let qualification =
            launch_profile("auths.opentofu.plan-preflight/1")?.qualification_for(flavor)?;
        values.push(RegisteredLocalProfile::new(
            ProfileAdvertisement::new(
                SessionProfileKey::new("auths.opentofu.plan-preflight", 1)
                    .map_err(|_| LocalAgentFailure::InvalidConfiguration)?,
                auths_opentofu::generated::profile_routes::PLANS_CREATE_RUNTIME_DIGEST,
                "auths.profile-operation/1",
                auths_opentofu::generated::profile_routes::PLANS_CREATE_ERROR_DIGEST,
                Some(
                    ProfileConnectionAdvertisement::new(
                        "opentofu",
                        "auths.opentofu.connection/1",
                        "auths.opentofu.connection-descriptor/1",
                    )
                    .map_err(|_| LocalAgentFailure::InvalidConfiguration)?,
                ),
                qualification,
            )
            .map_err(|_| LocalAgentFailure::InvalidConfiguration)?,
            4194304usize,
            None,
        )?);
    }
    if RegisteredProfile::OpentofuSavedPlansApply.is_available_for(flavor) {
        let qualification =
            launch_profile("auths.opentofu.saved-plan-apply/1")?.qualification_for(flavor)?;
        values.push(RegisteredLocalProfile::new(
            ProfileAdvertisement::new(
                SessionProfileKey::new("auths.opentofu.saved-plan-apply", 1)
                    .map_err(|_| LocalAgentFailure::InvalidConfiguration)?,
                auths_opentofu::generated::profile_routes::SAVED_PLANS_APPLY_RUNTIME_DIGEST,
                "auths.profile-operation/1",
                auths_opentofu::generated::profile_routes::SAVED_PLANS_APPLY_ERROR_DIGEST,
                Some(
                    ProfileConnectionAdvertisement::new(
                        "opentofu",
                        "auths.opentofu.connection/1",
                        "auths.opentofu.connection-descriptor/1",
                    )
                    .map_err(|_| LocalAgentFailure::InvalidConfiguration)?,
                ),
                qualification,
            )
            .map_err(|_| LocalAgentFailure::InvalidConfiguration)?,
            4096usize,
            None,
        )?);
    }
    if RegisteredProfile::PostgresqlUpdatesExecute.is_available_for(flavor) {
        let qualification =
            launch_profile("auths.postgresql.bounded-update/1")?.qualification_for(flavor)?;
        values.push(RegisteredLocalProfile::new(
            ProfileAdvertisement::new(
                SessionProfileKey::new("auths.postgresql.bounded-update", 1)
                    .map_err(|_| LocalAgentFailure::InvalidConfiguration)?,
                auths_postgresql::generated::profile_routes::UPDATES_EXECUTE_RUNTIME_DIGEST,
                "auths.profile-operation/1",
                auths_postgresql::generated::profile_routes::UPDATES_EXECUTE_ERROR_DIGEST,
                Some(
                    ProfileConnectionAdvertisement::new(
                        "postgresql",
                        "auths.postgresql.connection/1",
                        "auths.postgresql.connection-descriptor/1",
                    )
                    .map_err(|_| LocalAgentFailure::InvalidConfiguration)?,
                ),
                qualification,
            )
            .map_err(|_| LocalAgentFailure::InvalidConfiguration)?,
            4096usize,
            None,
        )?);
    }
    if RegisteredProfile::PostgresqlUpdatePreflightsCreate.is_available_for(flavor) {
        let qualification =
            launch_profile("auths.postgresql.update-preflight/1")?.qualification_for(flavor)?;
        values.push(RegisteredLocalProfile::new(ProfileAdvertisement::new(SessionProfileKey::new("auths.postgresql.update-preflight", 1).map_err(|_| LocalAgentFailure::InvalidConfiguration)?, auths_postgresql::generated::profile_routes::UPDATE_PREFLIGHTS_CREATE_RUNTIME_DIGEST, "auths.profile-operation/1", auths_postgresql::generated::profile_routes::UPDATE_PREFLIGHTS_CREATE_ERROR_DIGEST, Some(ProfileConnectionAdvertisement::new("postgresql", "auths.postgresql.connection/1", "auths.postgresql.connection-descriptor/1").map_err(|_| LocalAgentFailure::InvalidConfiguration)?), qualification).map_err(|_| LocalAgentFailure::InvalidConfiguration)?, 262144usize, None)?);
    }
    if RegisteredProfile::StripeRefundsCreate.is_available_for(flavor) {
        let qualification = launch_profile("auths.stripe.refund/1")?.qualification_for(flavor)?;
        values.push(RegisteredLocalProfile::new(
            ProfileAdvertisement::new(
                SessionProfileKey::new("auths.stripe.refund", 1)
                    .map_err(|_| LocalAgentFailure::InvalidConfiguration)?,
                auths_stripe::generated::profile_routes::REFUNDS_CREATE_RUNTIME_DIGEST,
                "auths.profile-operation/1",
                auths_stripe::generated::profile_routes::REFUNDS_CREATE_ERROR_DIGEST,
                Some(
                    ProfileConnectionAdvertisement::new(
                        "stripe",
                        "auths.stripe.connection/1",
                        "auths.stripe.connection-descriptor/1",
                    )
                    .map_err(|_| LocalAgentFailure::InvalidConfiguration)?,
                ),
                qualification,
            )
            .map_err(|_| LocalAgentFailure::InvalidConfiguration)?,
            262144usize,
            Some("protected-lease"),
        )?);
    }
    values.sort_by(|left, right| {
        left.advertisement()
            .profile()
            .cmp(right.advertisement().profile())
    });
    Ok(values)
}

